preConditionHook:
// The close is above the moving average (long) / below it (short), by an
// optional margin measured in ATRs. At the default marginAtr = 0 this is the
// bare close-beyond test the sources treat as canonical. The margin is in
// ATRs rather than the source's 4 ticks because MinMove/PriceScale are
// unregistered and the engine exposes no tick size.
//
// MultiWalk's WFSafe_Xaverage, ported from EmaGapBar (the EMA reference,
// which carries the full measurements). In short, from
// EL_XAverage_Probe.txt (@OJ 240min, chart starts 2007 and 2010):
//   * the wrapper is BIT-IDENTICAL to the plain XAverage built-in at a fixed
//     length -- (wf - xa) * 1e12 printed exactly 0.0000 on all 17,785 bars;
//   * the SEED is the PRICE on the study's first calculated bar
//     (ctx.CurrentBar() == 1), not a length-term simple average, and an EMA
//     never forgets its seed -- it only decays at (1 - sf)^n, ~330 bars;
//   * the recurrence is x + sf*(p - x), ONE statement, not sf*p + (1-sf)*x:
//     the two separated on 67% of probed bars past 100;
//   * there is NO warm-up hole -- do not add a bar-count guard returning 0;
//   * UNMEASURED: a walkforward length change, so emaLength is PINNED in the
//     grid; and the lagged read XAverage(...)[k], which this rule does not
//     need because it reads the current value only.
const double emaSf = 2.0 / (emaLength + 1.0);
if (ctx.CurrentBar() == 1) {
    emaVal = close[0];
} else {
    emaVal = emaVal + emaSf * (close[0] - emaVal);
}
// WFSafe_AvgTrueRange: MultiWalk's ROLLING accumulator, ported from
// AtrProfitTarget (the reference, with the measurements). Seeded with a full
// sum on the first calculated bar or when the length changes, and updated
// thereafter as TWO statements -- EL evaluates S[1] + in - out left to right, and
// folding it to S += in - out rounds differently (@OJ 2015-02-20).
if (atrLength != (int)atrLookback) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLookback; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLength = (int)atrLookback;
} else {
    const int out = (int)atrLookback;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atr = atrSum / (int)atrLookback;
margin = marginAtr * atr;
